window.docContents[27].resolve({"/part-5-applications/#part-5-applications":{"contents":"In Part V, the machinery of hyperfinite sets, enlargements, and countable saturation pays off across four seemingly distant branches of mathematics: measure and probability theory (Ch. 16), infinitary and finitary Ramsey combinatorics (Ch. 17), metric, Banach, p-adic, and power-series completions (Ch. 18), and functional analysis and Stone duality (Ch. 19), followed by Chapter 20's historical reading guide.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lectures on the Hyperreals — Interactive Lean 4 & Spatial Edition","header":"5. Part V — Landmark Applications & Reading Guide","id":"/part-5-applications/#part-5-applications"}});